loader:
(()=>{
 const load=(img)=>{
  if(!img?.dataset.deferredSrc)return Promise.resolve();
  img.loading='eager';img.decoding='async';
  if(img.dataset.deferredSrcset){img.srcset=img.dataset.deferredSrcset;delete img.dataset.deferredSrcset;}
  img.src=img.dataset.deferredSrc;delete img.dataset.deferredSrc;
  return typeof img.decode==='function'?img.decode().catch(()=>{}):Promise.resolve();
 };
 const hydrate=(area)=>{area.querySelectorAll('img[data-deferred-src]').forEach(load);};
 const areas=[document.getElementById('people'),document.getElementById('how')].filter(Boolean);
 const nearby=(area)=>{const r=area.getBoundingClientRect();return r.top<innerHeight+1200&&r.bottom>-1200;};
 const warm=(area)=>{
  if(!nearby(area))return;
  const active=area.querySelector('.people-visual.current')||area.querySelector('.scene-art.active');
  if(!active)return;
  const current=active.matches('img')?[active]:[...active.querySelectorAll('img')];
  // Keep visible art first in line. Only one neighboring scene follows decoding.
  Promise.all(current.map(load)).then(()=>{
   if(!nearby(area))return;
   const index=Number(active.dataset.aud??active.dataset.scene);
   const next=area.querySelector('.people-visual[data-aud="'+(index+1)+'"] img')||area.querySelector('img.scene-art[data-scene="'+(index+1)+'"]');
   if(next)load(next);
  });
 };
 if('IntersectionObserver' in window){
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)warm(e.target);}),{rootMargin:'1200px 0px'});
  areas.forEach(area=>observer.observe(area));
 }else{areas.forEach(hydrate);}
 if('MutationObserver' in window){
  const recover=new MutationObserver(()=>areas.forEach(warm));
  areas.forEach(area=>recover.observe(area,{attributes:true,subtree:true,attributeFilter:['class']}));
 }
})();
